import mongoose, { Types } from 'mongoose';
import { z } from 'zod';
import { revalidatePath, revalidateTag, TAGS } from '@/lib/cache';
import ProductModel, { type ProductDocument } from '../models/Product';
import ProductTypeModel, { type AttributeDef, type ColorValue } from '../models/ProductType';
import { buildProductValidator } from '../validation/productZod';
import { objectIdString } from '../validation/sharedSchemas';
import CategoryModel from '../models/Category';
import { syncServiceStock } from '@/sync/service-stock';


/**
 * Sanitize a slug generated by AI/LLM before saving.
 * Converts Persian/Arabic to latin, removes invalid chars,
 * ensures valid format for URL.
 */
function sanitizeSlug(slug: string, fallbackTitle?: string): string {
  if (!slug || slug.trim().length === 0) {
    return generateSlugFromTitle(fallbackTitle || 'product');
  }
  let s = slug.toLowerCase().trim();
  // Persian/Arabic to latin transliteration
  const persianMap: Record<string, string> = {
    'آ': 'a', 'ا': 'a', 'ب': 'b', 'پ': 'p', 'ت': 't', 'ث': 's',
    'ج': 'j', 'چ': 'ch', 'ح': 'h', 'خ': 'kh', 'د': 'd', 'ذ': 'z',
    'ر': 'r', 'ز': 'z', 'ژ': 'zh', 'س': 's', 'ش': 'sh', 'ص': 's',
    'ض': 'z', 'ط': 't', 'ظ': 'z', 'ع': 'a', 'غ': 'gh', 'ف': 'f',
    'ق': 'gh', 'ک': 'k', 'گ': 'g', 'ل': 'l', 'م': 'm', 'ن': 'n',
    'و': 'v', 'ه': 'h', 'ی': 'y', 'ء': '', 'ئ': 'y', 'ؤ': 'o',
    'ة': 'h', 'إ': 'a', 'أ': 'a', 'ى': 'a',
    // Persian/Arabic digits
    '۰': '0', '۱': '1', '۲': '2', '۳': '3', '۴': '4',
    '۵': '5', '۶': '6', '۷': '7', '۸': '8', '۹': '9',
    '٠': '0', '١': '1', '٢': '2', '٣': '3', '٤': '4',
    '٥': '5', '٦': '6', '٧': '7', '٨': '8', '٩': '9',
  };
  // Replace Persian/Arabic chars
  for (const [persian, latin] of Object.entries(persianMap)) {
    s = s.split(persian).join(latin);
  }
  // Remove emoji and other non-ASCII
  s = s.replace(/[^a-z0-9]+/g, '-');
  // Remove leading/trailing hyphens
  s = s.replace(/^-+|-+$/g, '');
  // Limit length
  s = s.slice(0, 100);
  if (!s || s.length < 2) {
    return generateSlugFromTitle(fallbackTitle || 'product');
  }
  return s;
}

function generateSlugFromTitle(title: string): string {
  let s = String(title || 'product').toLowerCase().trim();
  const persianMap: Record<string, string> = {
    'آ': 'a', 'ا': 'a', 'ب': 'b', 'پ': 'p', 'ت': 't', 'ث': 's',
    'ج': 'j', 'چ': 'ch', 'ح': 'h', 'خ': 'kh', 'د': 'd', 'ذ': 'z',
    'ر': 'r', 'ز': 'z', 'ژ': 'zh', 'س': 's', 'ش': 'sh', 'ص': 's',
    'ض': 'z', 'ط': 't', 'ظ': 'z', 'ع': 'a', 'غ': 'gh', 'ف': 'f',
    'ق': 'gh', 'ک': 'k', 'گ': 'g', 'ل': 'l', 'م': 'm', 'ن': 'n',
    'و': 'v', 'ه': 'h', 'ی': 'y', 'ء': '', 'ئ': 'y',
    '۰': '0', '۱': '1', '۲': '2', '۳': '3', '۴': '4',
    '۵': '5', '۶': '6', '۷': '7', '۸': '8', '۹': '9',
  };
  for (const [persian, latin] of Object.entries(persianMap)) {
    s = s.split(persian).join(latin);
  }
  s = s.replace(/[^a-z0-9]+/g, '-');
  s = s.replace(/^-+|-+$/g, '');
  if (!s || s.length < 3) {
    s = 'product-' + Date.now().toString(36);
  }
  return s.slice(0, 100);
}


const PRODUCT_COLLECTION_PATHS = ['/products', '/store'];

function syncStockInBackground(
  variants: Array<{ barcode?: string; inventory?: { quantity?: number } }>,
): void {
  const payload = variants
    .filter((variant) => !!variant.barcode)
    .map((variant) => ({
      barcode: variant.barcode as string,
      stock: Math.max(0, Number(variant.inventory?.quantity ?? 0) || 0),
    }));

  if (!payload.length) return;

  void syncServiceStock(payload).catch((error) => {
    console.error('Background product stock sync failed', error);
  });
}

async function revalidateCategoryPaths(categoryIds: Types.ObjectId[]): Promise<void> {
  if (!categoryIds.length) {
    return;
  }
  const categories = await CategoryModel.find({ _id: { $in: categoryIds } }, { path: 1 }).lean();
  const paths = categories
    .map((category) => category?.path)
    .filter((path): path is string => typeof path === 'string' && path.length > 0);
  if (paths.length === 0) {
    return;
  }
  await Promise.all(paths.map((path) => revalidatePath(`/category/${path}`)));
}

async function revalidateProductCaches(slug: string, categoryIds: Types.ObjectId[] = []): Promise<void> {
  await Promise.all([
    revalidateTag(TAGS.PRODUCT(slug)),
    revalidateTag(TAGS.CATALOG),
    revalidateTag(TAGS.PRODUCT_LIST),
    revalidateTag(TAGS.CATEGORY_TREE),
  ]);

  await Promise.all([
    revalidatePath(`/product/${slug}`),
    ...PRODUCT_COLLECTION_PATHS.map((path) => revalidatePath(path)),
  ]);

  await revalidateCategoryPaths(categoryIds);
}

export function effectiveUnitPrice(
  variant: ProductDocument['variants'][number],
  now: Date = new Date(),
): number {
  const base = variant.price.amount;
  const offer = variant.offer;
  const active =
    !!offer &&
    (!offer.startsAt || now >= offer.startsAt) &&
    (!offer.endsAt || now <= offer.endsAt);
  const discount = active ? offer.amount : 0;
  return Math.max(0, base - discount);
}

function toObjectId(id: string): Types.ObjectId {
  return new mongoose.Types.ObjectId(id);
}

function normalizeVariantCode(value: unknown): string | undefined {
  if (value === undefined || value === null) return undefined;
  const normalized = String(value).trim();
  return normalized.length > 0 ? normalized : undefined;
}

function assertNoDuplicateVariantIdentifiers(
  variants: Array<{ sku?: string; barcode?: string }>,
): void {
  const seenSkus = new Map<string, number>();
  const seenBarcodes = new Map<string, number>();

  variants.forEach((variant, index) => {
    const sku = normalizeVariantCode(variant.sku);
    if (sku) {
      const previous = seenSkus.get(sku);
      if (previous !== undefined) {
        throw new Error(`شناسه واریانت تکراری است: ${sku} در ردیف‌های ${previous + 1} و ${index + 1}`);
      }
      seenSkus.set(sku, index);
    }

    const barcode = normalizeVariantCode(variant.barcode);
    if (barcode) {
      const previous = seenBarcodes.get(barcode);
      if (previous !== undefined) {
        throw new Error(`کد حسابداری/بارکد تکراری است: ${barcode} در ردیف‌های ${previous + 1} و ${index + 1}`);
      }
      seenBarcodes.set(barcode, index);
    }
  });
}

async function assertVariantIdentifiersAvailable(
  variants: Array<{ sku?: string; barcode?: string }>,
  excludeProductId?: Types.ObjectId | string,
): Promise<void> {
  const skus = Array.from(new Set(variants.map((variant) => normalizeVariantCode(variant.sku)).filter(Boolean))) as string[];
  const barcodes = Array.from(new Set(variants.map((variant) => normalizeVariantCode(variant.barcode)).filter(Boolean))) as string[];

  const or: Record<string, unknown>[] = [];
  if (skus.length) {
    or.push({ 'variants.sku': { $in: skus } });
  }
  if (barcodes.length) {
    or.push({ 'variants.barcode': { $in: barcodes } });
  }
  if (!or.length) return;

  const query: Record<string, unknown> = { $or: or };
  if (excludeProductId) {
    query._id = { $ne: typeof excludeProductId === 'string' ? new Types.ObjectId(excludeProductId) : excludeProductId };
  }

  const conflicts = await ProductModel.find(query, { title: 1, slug: 1, variants: 1 }).lean();
  for (const product of conflicts) {
    for (const variant of product.variants ?? []) {
      const sku = normalizeVariantCode(variant.sku);
      if (sku && skus.includes(sku)) {
        throw new Error(`شناسه واریانت تکراری است: ${sku} قبلاً در محصول «${product.title}» ثبت شده است`);
      }
      const barcode = normalizeVariantCode(variant.barcode);
      if (barcode && barcodes.includes(barcode)) {
        throw new Error(`کد حسابداری/بارکد تکراری است: ${barcode} قبلاً در محصول «${product.title}» ثبت شده است`);
      }
    }
  }
}

function preserveExistingVariantIds<T extends { sku?: string; barcode?: string }>(
  variants: T[],
  existingVariants: ProductDocument['variants'],
): Array<T & { _id?: Types.ObjectId }> {
  const bySku = new Map<string, ProductDocument['variants'][number]>();
  const byBarcode = new Map<string, ProductDocument['variants'][number]>();

  existingVariants.forEach((variant) => {
    const sku = normalizeVariantCode(variant.sku);
    const barcode = normalizeVariantCode(variant.barcode);
    if (sku) bySku.set(sku, variant);
    if (barcode) byBarcode.set(barcode, variant);
  });

  return variants.map((variant) => {
    const sku = normalizeVariantCode(variant.sku);
    const barcode = normalizeVariantCode(variant.barcode);
    const existing = (sku ? bySku.get(sku) : undefined) || (barcode ? byBarcode.get(barcode) : undefined);
    return existing?._id ? { ...variant, _id: existing._id } : variant;
  });
}

function extractAttributeValue(
  attributes: { key: string; value: unknown }[],
  key: string,
): unknown | undefined {
  return attributes.find((attr) => attr.key === key)?.value;
}

function collectSearchableValues(
  defs: AttributeDef[],
  values: { key: string; value: unknown }[],
): string[] {
  const output: string[] = [];
  defs
    .filter((attr) => attr.searchable)
    .forEach((attr) => {
      const value = extractAttributeValue(values, attr.key);
      if (value === undefined || value === null) return;
      if (attr.kind === 'color') {
        if (typeof value === 'string') {
          output.push(value);
        } else if (typeof value === 'object' && value !== null) {
          const color = value as ColorValue;
          output.push(color.name);
          output.push(color.key);
          if (Array.isArray(color.aliases)) {
            color.aliases.forEach((alias) => output.push(alias));
          }
        }
        return;
      }
      if (Array.isArray(value)) {
        value.forEach((item) => output.push(String(item)));
      } else {
        output.push(String(value));
      }
    });
  return output;
}

function materializeFilterableAttributes(
  defs: AttributeDef[],
  globalValues: { key: string; value: unknown }[],
  variants: { attributeValues: { key: string; value: unknown }[] }[],
): Record<string, unknown> {
  const mat: Record<string, unknown> = {};
  const filterableGlobals = defs.filter((attr) => attr.filterable && !attr.variant);
  const filterableVariants = defs.filter((attr) => attr.filterable && attr.variant);

  filterableGlobals.forEach((attr) => {
    const value = extractAttributeValue(globalValues, attr.key);
    if (value !== undefined) {
      const serialized = serializeFilterableValue(attr, value);
      if (serialized !== undefined) {
        mat[attr.key] = serialized;
      }
    }
  });

  filterableVariants.forEach((attr) => {
    const set = new Set<unknown>();
    variants.forEach((variant) => {
      const value = extractAttributeValue(variant.attributeValues, attr.key);
      if (value === undefined || value === null) return;
      const serialized = serializeFilterableValue(attr, value);
      if (Array.isArray(serialized)) {
        serialized.forEach((item) => set.add(item));
      } else if (serialized !== undefined) {
        set.add(serialized);
      }
    });
    if (set.size > 0) {
      mat[attr.key] = Array.from(set);
    }
  });

  return mat;
}

function serializeFilterableValue(attr: AttributeDef, value: unknown): unknown | unknown[] {
  if (value === undefined || value === null) {
    return undefined;
  }
  if (Array.isArray(value)) {
    const collected: unknown[] = [];
    value.forEach((item) => {
      const serialized = serializeFilterableValue(attr, item);
      if (Array.isArray(serialized)) {
        collected.push(...serialized);
      } else if (serialized !== undefined) {
        collected.push(serialized);
      }
    });
    return collected.length > 0 ? collected : undefined;
  }
  if (attr.kind === 'color') {
    if (typeof value === 'object') {
      const color = value as Partial<ColorValue>;
      return color.key ?? undefined;
    }
    return value;
  }
  return value;
}

async function loadProductType(productTypeId: string) {
  const productType = await ProductTypeModel.findById(productTypeId).exec();
  if (!productType) {
    throw new Error('ProductType not found');
  }
  return productType;
}

function computeSearchableText(
  title: string,
  brand: string | undefined,
  productTypeDefs: AttributeDef[],
  globalValues: { key: string; value: unknown }[],
  variants: { attributeValues: { key: string; value: unknown }[] }[],
): string {
  const pieces: string[] = [title];
  if (brand) pieces.push(brand);
  pieces.push(...collectSearchableValues(productTypeDefs.filter((attr) => !attr.variant), globalValues));
  variants.forEach((variant) => {
    pieces.push(
      ...collectSearchableValues(
        productTypeDefs.filter((attr) => attr.variant),
        variant.attributeValues,
      ),
    );
  });
  return pieces
    .filter((part) => typeof part === 'string' && part.trim().length > 0)
    .map((part) => part.toLowerCase())
    .join(' ');
}

function findColorAttribute(defs: AttributeDef[]): (AttributeDef & { values: ColorValue[] }) | undefined {
  return defs.find((attr): attr is AttributeDef & { values: ColorValue[] } => {
    return attr.kind === 'color' && Array.isArray(attr.values) && attr.values.length > 0;
  });
}

function buildColorMap(attribute: AttributeDef & { values: ColorValue[] }): Map<string, ColorValue> {
  const map = new Map<string, ColorValue>();
  attribute.values.forEach((value) => {
    map.set(value.key.toLowerCase(), value);
    map.set(value.name.trim().toLowerCase(), value);
    const slug = slugifyColorName(value.name);
    if (slug) {
      map.set(slug, value);
    }
    if (Array.isArray(value.aliases)) {
      value.aliases.forEach((alias) => {
        const trimmed = alias.trim().toLowerCase();
        if (trimmed) {
          map.set(trimmed, value);
          const aliasSlug = slugifyColorName(alias);
          if (aliasSlug) {
            map.set(aliasSlug, value);
          }
        }
      });
    }
  });
  return map;
}

function slugifyColorName(input: string): string {
  return input
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .replace(/-{2,}/g, '-');
}

type CanonicalColorResult = {
  value: ColorValue;
  colorKey: string;
  colorName: string;
  colorSwatches: string[];
  colorFamily?: string;
};

function canonicalizeColorInput(
  input: unknown,
  attribute: AttributeDef & { values: ColorValue[] },
  map: Map<string, ColorValue>,
  variantSku: string,
): CanonicalColorResult | null {
  if (input === undefined || input === null) {
    return null;
  }

  let key: string | undefined;
  if (typeof input === 'string') {
    key = input.trim();
  } else if (typeof input === 'object') {
    const value = input as Partial<ColorValue>;
    if (typeof value.key === 'string') {
      key = value.key.trim();
    }
  }

  if (!key) {
    throw new Error(`Variant ${variantSku}: invalid color value for attribute ${attribute.key}`);
  }

  let canonical = map.get(key.toLowerCase());
  if (!canonical) {
    canonical = map.get(slugifyColorName(key));
  }
  if (!canonical) {
    throw new Error(`Variant ${variantSku}: color key ${key} is not defined for attribute ${attribute.key}`);
  }
  if (canonical.active === false) {
    throw new Error(`Variant ${variantSku}: color ${canonical.key} is inactive`);
  }

  const cloned: ColorValue = {
    ...canonical,
    swatches: [...canonical.swatches],
    aliases: canonical.aliases ? [...canonical.aliases] : undefined,
  };

  return {
    value: cloned,
    colorKey: canonical.key,
    colorName: canonical.name,
    colorSwatches: [...canonical.swatches],
    colorFamily: canonical.family ?? (canonical.swatches.length > 1 ? 'multi' : undefined),
  };
}

function canonicalizeVariant(
  variant: any,
  colorAttribute: (AttributeDef & { values: ColorValue[] }) | undefined,
  colorMap: Map<string, ColorValue> | undefined,
): {
  sku: string;
  attributeValues: { key: string; value: unknown }[];
  price: unknown;
  offer?: unknown;
  inventory: unknown;
  mediaIds?: Types.ObjectId[];
  barcode?: string;
  active: boolean;
  colorKey?: string;
  colorName?: string;
  colorSwatches?: string[];
  colorFamily?: string;
  minimumOrderQuantity?: number;
  maximumOrderQuantity?: number;
} {
  const attributeValues = Array.isArray(variant.attributeValues) ? [...variant.attributeValues] : [];
  let colorResult: CanonicalColorResult | null = null;

  if (colorAttribute && colorMap) {
    const index = attributeValues.findIndex((attr) => attr.key === colorAttribute.key);
    if (index >= 0) {
      colorResult = canonicalizeColorInput(attributeValues[index].value, colorAttribute, colorMap, variant.sku);
      if (colorResult) {
        attributeValues[index] = {
          key: colorAttribute.key,
          value: colorResult.value,
        };
      }
    }
  }

  let weightIndex = attributeValues.findIndex((attr) => attr.key === 'weightGrams');
  let rawWeight = attributeValues[weightIndex]?.value;
  if (weightIndex < 0) {
    const legacyIndex = attributeValues.findIndex((attr) => attr.key === 'weight');
    if (legacyIndex >= 0) {
      weightIndex = legacyIndex;
      rawWeight = attributeValues[legacyIndex]?.value;
    }
  }

  if (weightIndex < 0) {
    throw new Error(`Variant ${variant.sku}: weightGrams attribute is required`);
  }

  let weightNumeric: number | undefined;
  if (typeof rawWeight === 'number' && Number.isFinite(rawWeight)) {
    weightNumeric = rawWeight;
  } else if (typeof rawWeight === 'string' && rawWeight.trim().length > 0) {
    const parsed = Number(rawWeight);
    if (Number.isFinite(parsed)) {
      weightNumeric = parsed;
    }
  }
  if (weightNumeric === undefined || weightNumeric <= 0) {
    throw new Error(`Variant ${variant.sku}: weightGrams must be a positive number`);
  }
  attributeValues[weightIndex] = {
    key: 'weightGrams',
    value: Math.max(1, Math.round(weightNumeric)),
  };

  return {
    sku: normalizeVariantCode(variant.sku) ?? '',
    attributeValues,
    price: variant.price,
    offer: variant.offer,
    inventory: variant.inventory,
    mediaIds: Array.isArray(variant.mediaIds)
      ? variant.mediaIds.map((id: string) => toObjectId(id))
      : undefined,
    barcode: normalizeVariantCode(variant.barcode),
    active: variant.active ?? true,
    colorKey: colorResult?.colorKey,
    colorName: colorResult?.colorName,
    colorSwatches: colorResult?.colorSwatches,
    colorFamily: colorResult?.colorFamily,
    minimumOrderQuantity: variant.minimumOrderQuantity,
    maximumOrderQuantity: variant.maximumOrderQuantity
  };
}
function withDefaultVariantTrackingUnits(payload: unknown): unknown {
  if (!payload || typeof payload !== 'object' || !Array.isArray((payload as any).variants)) {
    return payload;
  }

  let changed = false;
  const variants = (payload as any).variants.map((variant: any) => {
    if (variant?.inventory?.trackingUnit) {
      return variant;
    }
    changed = true;
    return {
      ...variant,
      inventory: {
        ...variant?.inventory,
        trackingUnit: 'unit',
      },
    };
  });

  return changed ? { ...(payload as any), variants } : payload;
}

export async function createProduct(payload: unknown): Promise<ProductDocument> {
  const { productTypeId } = z.object({ productTypeId: objectIdString }).parse(payload);
  const productType = await loadProductType(productTypeId);
  const validator = buildProductValidator(productType);
  // The product validator schema is dynamic per product type attributes.
  const parsed = validator.productSchema.parse(withDefaultVariantTrackingUnits(payload)) as any;

  const colorAttribute = findColorAttribute(productType.attributes);
  const colorMap = colorAttribute ? buildColorMap(colorAttribute) : undefined;

  const categories = (parsed.categories ?? []).map((id: string) => toObjectId(id));
  if (categories.length > 0) {
    const found = await CategoryModel.countDocuments({ _id: { $in: categories } });
    if (found !== categories.length) {
      throw new Error('One or more categories not found');
    }
  }

  const variants: ReturnType<typeof canonicalizeVariant>[] = parsed.variants.map((variant: any) =>
    canonicalizeVariant(variant, colorAttribute, colorMap),
  );
  assertNoDuplicateVariantIdentifiers(variants);
  await assertVariantIdentifiersAvailable(variants);

  const attrs = materializeFilterableAttributes(productType.attributes, parsed.attributeValues, variants);
  if (colorAttribute) {
    const colorKeys = new Set<string>();
    const colorFamilies = new Set<string>();
    variants.forEach((variant) => {
      if (variant.colorKey) {
        colorKeys.add(variant.colorKey);
      }
      if (variant.colorFamily) {
        colorFamilies.add(variant.colorFamily);
      }
    });
    if (colorKeys.size > 0) {
      attrs[colorAttribute.key] = Array.from(colorKeys);
    }
    if (colorFamilies.size > 0) {
      attrs[`${colorAttribute.key}Family`] = Array.from(colorFamilies);
    }
  }
  const searchableText = computeSearchableText(
    parsed.title,
    parsed.brand,
    productType.attributes,
    parsed.attributeValues,
    variants,
  );

  const doc = await ProductModel.create({
    productTypeId: productType._id,
    typeVersion: productType.version,
    title: parsed.title,
    slug: sanitizeSlug(parsed.slug, parsed.title),
    description: parsed.description,
    brand: parsed.brand,
    seoTitle: parsed.seoTitle,
    seoDescription: parsed.seoDescription,
    attributeValues: parsed.attributeValues,
    variants,
    categories,
    attrs,
    searchableText,
    showInCart: parsed.showInCart ?? false,
    status: parsed.status ?? 'draft',
  });


  syncStockInBackground(doc.variants);
  await revalidateProductCaches(doc.slug, categories);
  return doc;
}

export async function getProduct(id: string): Promise<ProductDocument | null> {
  return ProductModel.findById(id).exec();
}

export async function updateProduct(
  id: string,
  payload: unknown,
): Promise<ProductDocument | null> {
  const product = await ProductModel.findById(id).exec();
  if (!product) {
    return null;
  }
  const previousSlug = product.slug;
  const productType = await loadProductType(product.productTypeId.toString());
  const validator = buildProductValidator(productType);
  // Mirror createProduct: backfill the default trackingUnit on variants so an
  // edit that omits it (it already lives in the DB) isn't rejected by the schema.
  const parsed = validator.productSchema.parse(withDefaultVariantTrackingUnits(payload)) as any;



  const colorAttribute = findColorAttribute(productType.attributes);
  const colorMap = colorAttribute ? buildColorMap(colorAttribute) : undefined;

  const categories = (parsed.categories ?? []).map((id: string) => toObjectId(id));
  if (categories.length > 0) {
    const found = await CategoryModel.countDocuments({ _id: { $in: categories } });
    if (found !== categories.length) {
      throw new Error('One or more categories not found');
    }
  }

  const canonicalVariants: ReturnType<typeof canonicalizeVariant>[] = parsed.variants.map((variant: any) =>
    canonicalizeVariant(variant, colorAttribute, colorMap),
  );
  const variants = preserveExistingVariantIds(canonicalVariants, product.variants);
  assertNoDuplicateVariantIdentifiers(variants);
  await assertVariantIdentifiersAvailable(variants, product._id);

  const attrs = materializeFilterableAttributes(productType.attributes, parsed.attributeValues, variants);
  if (colorAttribute) {
    const colorKeys = new Set<string>();
    const colorFamilies = new Set<string>();
    variants.forEach((variant) => {
      if (variant.colorKey) {
        colorKeys.add(variant.colorKey);
      }
      if (variant.colorFamily) {
        colorFamilies.add(variant.colorFamily);
      }
    });
    if (colorKeys.size > 0) {
      attrs[colorAttribute.key] = Array.from(colorKeys);
    }
    if (colorFamilies.size > 0) {
      attrs[`${colorAttribute.key}Family`] = Array.from(colorFamilies);
    }
  }
  const searchableText = computeSearchableText(
    parsed.title,
    parsed.brand,
    productType.attributes,
    parsed.attributeValues,
    variants,
  );


  const update: Record<string, unknown> = {
    title: parsed.title,
    slug: sanitizeSlug(parsed.slug, parsed.title),
    description: parsed.description,
    brand: parsed.brand,
    seoTitle: parsed.seoTitle,
    seoDescription: parsed.seoDescription,
    attributeValues: parsed.attributeValues,
    variants,
    categories,
    attrs,
    searchableText,
    showInCart: parsed.showInCart ?? product.showInCart,
    status: parsed.status ?? product.status,
    typeVersion: productType.version,
  };


  const updated = await ProductModel.findByIdAndUpdate(id, update, { new: true, runValidators: true }).exec();
  if (updated) {
    syncStockInBackground(updated.variants);
    const categoryIds = (updated.categories ?? []).map((value) => new Types.ObjectId(value));
    await revalidateProductCaches(updated.slug, categoryIds);
    if (previousSlug !== updated.slug) {
      await Promise.all([
        revalidateTag(TAGS.PRODUCT(previousSlug)),
        revalidatePath(`/product/${previousSlug}`),
      ]);
    }
  }
  return updated;
}

export async function archiveProduct(id: string): Promise<ProductDocument | null> {
  const updated = await ProductModel.findByIdAndUpdate(
    id,
    { status: 'archived' },
    { new: true, runValidators: true },
  ).exec();
  if (updated) {
    const categoryIds = (updated.categories ?? []).map((value) => new Types.ObjectId(value));
    await revalidateProductCaches(updated.slug, categoryIds);
  }
  return updated;
}

/**
 * Set the publish status of many products at once (admin bulk action). Returns
 * the number of products actually modified. Invalidates the affected caches.
 */
export async function bulkUpdateProductStatus(
  ids: string[],
  status: 'draft' | 'active' | 'archived',
): Promise<number> {
  const objectIds = ids
    .filter((id) => Types.ObjectId.isValid(id))
    .map((id) => new Types.ObjectId(id));
  if (objectIds.length === 0) return 0;

  // Read the slugs/categories first so we can revalidate exactly what changed.
  const affected = await ProductModel.find({ _id: { $in: objectIds } }, { slug: 1, categories: 1 }).lean().exec();
  const result = await ProductModel.updateMany(
    { _id: { $in: objectIds } },
    { status },
    { runValidators: true },
  ).exec();

  await Promise.all(
    affected.map((p) => {
      const doc = p as unknown as { slug?: string; categories?: unknown[] };
      return revalidateProductCaches(
        String(doc.slug ?? ''),
        (doc.categories ?? []).map((value) => new Types.ObjectId(value as string)),
      );
    }),
  );
  return result.modifiedCount ?? 0;
}

export interface ListProductsParams {
  productTypeId?: string;
  categoryIds?: Types.ObjectId[];
  q?: string;
  attrFilters?: Record<string, string | string[]>;
  limit?: number;
  skip?: number;
  status?: ('draft' | 'active' | 'archived')[];
}

export async function listProducts(params: ListProductsParams) {
  const {
    productTypeId,
    categoryIds,
    q,
    attrFilters = {},
    limit = 20,
    skip = 0,
    status,
  } = params;

  const query: Record<string, unknown> = {};
  if (productTypeId) {
    query.productTypeId = new mongoose.Types.ObjectId(productTypeId);
  }
  if (categoryIds && categoryIds.length > 0) {
    query.categories = { $in: categoryIds };
  }
  if (q?.trim()) {
    const escaped = q.trim().replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = { $regex: escaped, $options: 'i' };
    query.$or = [
      { title: regex },
      { slug: regex },
      { brand: regex },
      { searchableText: regex },
      { 'variants.sku': regex },
      { 'variants.barcode': regex },
    ];
  }
  if (status && status.length > 0) {
    query.status = { $in: status };
  }
  const andFilters: Record<string, unknown>[] = [];
  Object.entries(attrFilters).forEach(([key, value]) => {
    const valuesArray = Array.isArray(value) ? value : [value];
    if (key === 'color') {
      andFilters.push({
        $or: [
          { 'variants.colorKey': { $in: valuesArray } },
          { [`attrs.${key}`]: { $in: valuesArray } },
        ],
      });
      return;
    }
    if (key === 'colorFamily') {
      andFilters.push({
        $or: [
          { 'variants.colorFamily': { $in: valuesArray } },
          { [`attrs.${key}`]: { $in: valuesArray } },
        ],
      });
      return;
    }
    if (Array.isArray(value)) {
      query[`attrs.${key}`] = { $in: value };
    } else {
      query[`attrs.${key}`] = value;
    }
  });
  if (andFilters.length > 0) {
    query.$and = [...((query.$and as Record<string, unknown>[]) ?? []), ...andFilters];
  }

  const items = await ProductModel.find(query)
    .sort({ createdAt: -1 })
    .skip(skip)
    .limit(Math.min(limit, 100))
    .exec();
  const total = await ProductModel.countDocuments(query);
  return { items, total };
}
